//! Integration tests over modules generated by libsword's own tools
//! (`osis2mod`, `imp2ld`, `imp2gbs`; see `tests/fixtures.tar.gz:gen.py`),
//! covering every driver, compression, block type and an enciphered module.
//! `ref/*.imp` are libsword's `mod2imp` dumps of the uncompressed variants.

use std::path::PathBuf;
use std::sync::OnceLock;
use sword_modules::*;

fn key(book: &str, chapter: u8, verse: u8) -> VerseKey {
    VerseKey::from_osis(book, chapter, verse).unwrap()
}

fn book(osis: &str) -> sword_modules::BookId {
    key(osis, 1, 1).book
}

fn root() -> &'static PathBuf {
    static ROOT: OnceLock<PathBuf> = OnceLock::new();
    ROOT.get_or_init(|| {
        let dir = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join("sword-fixtures");
        if !dir.join("mods.d").exists() {
            let f = std::fs::File::open(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures.tar.gz")).unwrap();
            tar::Archive::new(flate2::read::GzDecoder::new(f)).unpack(&dir).unwrap();
        }
        dir
    })
}

fn lib() -> SwordLibrary {
    SwordLibrary::open(root()).unwrap()
}

fn imp_bodies(name: &str) -> Vec<String> {
    let text = std::fs::read_to_string(root().join("ref").join(format!("{name}.imp"))).unwrap();
    let mut out = Vec::new();
    for chunk in text.split("$$$").skip(1) {
        let body = chunk.split_once('\n').map(|x| x.1).unwrap_or("").trim_end_matches('\n');
        if !body.is_empty() {
            out.push(body.to_string());
        }
    }
    out
}

fn all_verses(m: &VerseModule) -> Vec<(VerseKey, String)> {
    m.iter().map(|r| r.map(|(k, e)| (k, e.raw))).collect::<Result<_>>().unwrap()
}

#[test]
fn raw_text_matches_libsword() {
    let m = lib().open_module("TRaw").unwrap().into_verse().unwrap();
    let ours: Vec<String> = all_verses(&m).into_iter().map(|(_, t)| t).collect();
    let reference = imp_bodies("TRaw");
    // mod2imp also prints the testament headings (slot 1), which `iter()` skips.
    let reference: Vec<String> = reference.into_iter().filter(|t| !t.starts_with("<milestone type=\"x-importer\"")).collect();
    assert_eq!(ours, reference);
}

#[test]
fn every_bible_driver_and_compression_agrees() {
    let lib = lib();
    let base = all_verses(&lib.open_module("TRaw").unwrap().into_verse().unwrap());
    assert!(base.len() > 250);
    for name in ["TRaw4", "TZipBook", "TZipChap", "TZipVerse", "TLzss", "TBzip", "TXz", "TZip4", "TCiphZ", "TCom"] {
        let m = lib.open_module(name).unwrap_or_else(|e| panic!("{name}: {e}"));
        let m = m.into_verse().unwrap();
        assert_eq!(all_verses(&m), base, "{name}");
    }
    assert_eq!(lib.conf("TCom").unwrap().module_kind().unwrap(), ModuleKind::Commentary);
}

#[test]
fn verse_lookup_and_markup() {
    let m = lib().open_module("TZipChap").unwrap().into_verse().unwrap();
    assert_eq!(m.versification().name(), "KJVA");
    let e = m.verse(&key("John", 3, 14)).unwrap().unwrap();
    assert_eq!(e.markup, Markup::Osis);
    // generator: every 7th verse is words of Jesus, every 5th has a cross-reference note;
    // the markup is passed on as stored, entities and all
    assert!(e.raw.starts_with(r#"<q marker="" who="Jesus">"#), "{}", e.raw);
    assert!(e.raw.ends_with("</q> &amp;end."), "{}", e.raw);
    let v15 = m.verse(&key("John", 3, 15)).unwrap().unwrap();
    assert!(v15.raw.contains(r#"<note n="a" type="crossReference"><reference osisRef="John.3.16">John 3:16</reference></note>"#), "{}", v15.raw);
    // apocrypha in KJVA, intros, out-of-range
    assert!(m.verse(&key("Tob", 1, 1)).unwrap().is_some());
    assert!(m.verse(&key("John", 3, 99)).unwrap().is_none());
    assert_eq!(VerseKey::from_osis("Nope", 1, 1), None);
    let ch = m.chapter(book("Gen"), 1).unwrap();
    assert_eq!(ch.iter().filter(|(k, _)| k.verse > 0).count(), 31);
    assert!(m.has_book(book("Rev")).unwrap());
    assert!(!m.has_book(book("Exod")).unwrap());
    assert!(m.has_testament(Testament::Old) && m.has_testament(Testament::New));
}

#[test]
fn passages_from_topos() {
    let m = lib().open_module("TZipChap").unwrap().into_verse().unwrap();
    let data = sword_modules::bible_data();
    let keys = |reference: &str| -> Vec<String> {
        let passage = data.parse(reference).unwrap_or_else(|| panic!("{reference}"));
        m.passage(&passage).unwrap().into_iter().map(|(k, _)| k.to_string()).collect()
    };
    assert_eq!(keys("Jn 3:14-16"), ["John 3:14", "John 3:15", "John 3:16"]);
    assert_eq!(keys("Gen 1:31-2:1"), ["Genesis 1:31", "Genesis 2:1"]);
    assert_eq!(keys("Tob 1:1, 3"), ["Tobit 1:1", "Tobit 1:3"]);
    // A whole chapter uses the module's versification and leaves out the introduction
    let gen1 = keys("Gen 1");
    assert_eq!(gen1.len(), 31);
    assert_eq!(gen1[0], "Genesis 1:1");
    // Each key reads the same entry as `verse`
    let passage = data.parse("John 3:16").unwrap();
    let (k, e) = m.passage(&passage).unwrap().remove(0);
    assert_eq!(Some(e), m.verse(&k).unwrap());
    // Introductions have their own methods, matching `chapter`
    let gen = book("Gen");
    let intro = m.chapter(gen, 1).unwrap().into_iter().find(|(k, _)| k.verse == 0).map(|(_, e)| e);
    assert_eq!(m.chapter_intro(gen, 1).unwrap(), intro);
    assert_eq!(m.book_intro(gen).unwrap(), m.verse(&key("Gen", 0, 0)).unwrap());
}

#[test]
fn enciphered_module_needs_key() {
    let mut lib = lib();
    lib.conf_mut("TCiphZ").unwrap().set("CipherKey", "");
    assert!(matches!(lib.open_module("TCiphZ"), Err(Error::Locked(_))));
    let m = lib.open_module_with_key("TCiphZ", "s3cr3t-Key").unwrap().into_verse().unwrap();
    assert!(m.verse(&key("Gen", 1, 1)).unwrap().unwrap().raw.contains("end."));
    let wrong = lib.open_module_with_key("TCiphZ", "wrong").unwrap().into_verse().unwrap();
    assert!(wrong.verse(&key("Gen", 1, 1)).is_err(), "zlib should reject garbage");
}

#[test]
fn dictionaries() {
    let lib = lib();
    let raw = lib.open_module("LRaw").unwrap().into_dictionary().unwrap();
    let base: Vec<(String, String)> = raw.iter().map(|r| r.map(|(k, e)| (k, e.raw))).collect::<Result<_>>().unwrap();
    let reference = imp_bodies("LRaw");
    assert_eq!(base.iter().map(|(_, t)| t.clone()).collect::<Vec<_>>(), reference);
    for name in ["LRaw4", "LZip", "LLzss", "LBz"] {
        let d = lib.open_module(name).unwrap().into_dictionary().unwrap();
        let all: Vec<(String, String)> = d.iter().map(|r| r.map(|(k, e)| (k, e.raw))).collect::<Result<_>>().unwrap();
        assert_eq!(all, base, "{name}");
    }
    let d = lib.open_module("LZip").unwrap().into_dictionary().unwrap();
    // Strong's padding and case folding like libsword
    for k in ["25", "00025", "G25", "g25"] {
        assert!(d.get(k).unwrap().unwrap().raw.contains("Definition of 25"), "{k}");
    }
    assert!(d.get("AARON").unwrap().unwrap().raw.contains("Definition of aaron"));
    assert!(d.get("Ωmega").unwrap().is_some());
    assert_eq!(d.get("alias").unwrap().unwrap().raw, d.get("aaron").unwrap().unwrap().raw);
    assert!(d.get("nothing-here").unwrap().is_none());
    assert_eq!(d.get_nearest("word1").unwrap().unwrap().0, "WORD1");
    for number in ["G25", "g0025", " H25 ", "G25a"] {
        assert!(d.get_strongs(number).unwrap().unwrap().raw.contains("Definition of 25"), "{number}");
    }
    for number in ["G26", "25", "X25", "G", "G25-", "AARON"] {
        assert!(d.get_strongs(number).unwrap().is_none(), "{number}");
    }

    let cs = lib.open_module("LCase").unwrap().into_dictionary().unwrap();
    assert!(cs.get("aaron").unwrap().is_some());
    assert!(cs.get("AARON").unwrap().is_none());
}

#[test]
fn general_book() {
    let g = lib().open_module("GBook").unwrap().into_genbook().unwrap();
    let toc: Vec<(usize, String)> = g.walk().unwrap().into_iter().skip(1).map(|(d, n)| (d, n.name)).collect();
    assert_eq!(toc.len(), 12);
    assert_eq!(toc[0], (1, "Part 1".to_string()));
    assert_eq!(toc[1], (2, "Chapter 1".to_string()));
    let node = g.find("/Part 2/Chapter 3").unwrap().unwrap();
    assert_eq!(g.path(&node).unwrap(), "/Part 2/Chapter 3");
    let text = g.text(&node).unwrap().unwrap();
    assert_eq!(text.raw, "<p>Text of part 2 chapter 3 — ünïcödé</p>");
    assert_eq!(text.markup, Markup::Thml);
    assert!(g.find("/Part 9").unwrap().is_none());
    let parent = g.parent(&node).unwrap().unwrap();
    assert_eq!(parent.name, "Part 2");
    assert_eq!(g.children(&parent).unwrap().len(), 3);
}

